-- Errata reading for O31: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('conditions','labs')), dm AS (SELECT DISTINCT patient FROM (SELECT patient, lower(coalesce(json_extract(payload,'$.description'),'')) d, coalesce(json_extract(payload,'$.icd10'),'') i FROM r WHERE stream='conditions') WHERE (d LIKE '%diabet%' OR d LIKE 't1dm%' OR d LIKE 't2dm%' OR i LIKE 'E10%' OR i LIKE 'E11%') AND d NOT LIKE '%prediabet%' AND d NOT LIKE '%family history%' AND d NOT LIKE 'gdm%' AND i NOT LIKE 'O24%' AND i NOT LIKE 'Z83%'), eg AS (SELECT DISTINCT patient FROM r WHERE stream='labs' AND coalesce(json_extract(payload,'$.name'),json_extract(payload,'$.test'))='eGFR' AND json_extract(payload,'$.event_date') BETWEEN '2028-01-01' AND '2028-12-31' AND typeof(json_extract(payload,'$.value')) IN ('integer','real')), ua AS (SELECT DISTINCT patient FROM r WHERE stream='labs' AND coalesce(json_extract(payload,'$.name'),json_extract(payload,'$.test'))='Urine albumin/creatinine ratio' AND json_extract(payload,'$.event_date') BETWEEN '2028-01-01' AND '2028-12-31' AND typeof(json_extract(payload,'$.value')) IN ('integer','real')), den AS (SELECT dm.patient FROM dm JOIN patients p ON p.id=dm.patient WHERE coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported')) BETWEEN 18 AND 85) SELECT round(100.0*sum(den.patient IN (SELECT patient FROM eg) AND den.patient IN (SELECT patient FROM ua))/count(*),1) AS value FROM den;
